"""Orchestrate ingest → features → HHFormer → embeddings → CFR → solver grid → student."""from __future__ import annotationsimport asyncioimport jsonfrom dataclasses import dataclassfrom datetime import UTC, datetimefrom pathlib import Pathfrom poker_ai.config.settings import get_settingsfrom poker_ai.features.build import write_feature_jsonlfrom poker_ai.ingest.service import run_ingest_syncfrom poker_ai.learn.hhformer_inference import EmbedConfig, export_embeddings_jsonlfrom poker_ai.learn.pretrain_hhformer import PretrainConfig, run_pretrainfrom poker_ai.policy.cfr_policy import CFRPolicyfrom poker_ai.runtime.workers import resolve_worker_countfrom poker_ai.solver.solve_preflop import solve_preflopfrom poker_ai.store.db import get_async_session_factoryfrom poker_ai.store.migrate import upgrade_head@dataclass(frozen=True, slots=True)class PipelineConfig:    corpus: Path | None = None    workers: int | None = None    skip_ingest: bool = False    skip_features: bool = False    skip_train: bool = False    skip_embed: bool = False    skip_solve: bool = False    solver_grid: bool = False    train_student: bool = False    solver_grid_spots: int = 256    solver_backend: str = "auto"    student_epochs: int = 15    student_batch_size: int = 64    cache_dir: Path = Path("artifacts/solver_cache")    student_dir: Path = Path("artifacts/student/v1")    features_out: Path = Path("data/processed/features.jsonl")    embed_out: Path = Path("data/processed/hhformer_embeddings.jsonl")    hhformer_dir: Path = Path("artifacts/hhformer/v1")    preflop_6max_out: Path = Path("artifacts/solver/preflop_cfr.json")    preflop_hu_out: Path = Path("artifacts/solver/preflop_hu.json")    preflop_iters_6: int = 20_000    preflop_iters_hu: int = 15_000    chance_samples: int = 32    max_raises: int = 1@dataclass(frozen=True, slots=True)class PipelineResult:    hands_ingested: int    features_written: int    embeddings_written: int    preflop_6_info_sets: int    preflop_hu_info_sets: int    solver_spots_cached: int = 0    student_mse_val: float | None = Nonedef run_pipeline(cfg: PipelineConfig) -> PipelineResult:    """Run connected phases with shared worker count."""    settings = get_settings()    workers = resolve_worker_count(cfg.workers)    upgrade_head()    factory = get_async_session_factory()    hands_ingested = 0    if not cfg.skip_ingest and cfg.corpus is not None:        _, written = run_ingest_sync(            cfg.corpus,            session_factory=factory,            uid_secret=settings.player_uid_hmac_secret,            workers=workers,        )        hands_ingested = written    features_written = 0    if not cfg.skip_features:        async def _feat() -> int:            async with factory() as session:                return await write_feature_jsonl(session, cfg.features_out, workers=workers)        features_written = asyncio.run(_feat())    if not cfg.skip_train:        run_pretrain(            artifact_dir=cfg.hhformer_dir,            session_factory=factory,            cfg=PretrainConfig(num_workers=min(workers, 4)),        )    embeddings_written = 0    if not cfg.skip_embed:        embed_cfg = EmbedConfig(weights_dir=cfg.hhformer_dir, batch_size=256)        embeddings_written = export_embeddings_jsonl(factory, cfg.embed_out, cfg=embed_cfg)    preflop_6 = 0    preflop_hu = 0    if not cfg.skip_solve:        r6 = solve_preflop(            num_players=6,            iterations=cfg.preflop_iters_6,            chance_samples=cfg.chance_samples,            workers=workers,            max_raises=cfg.max_raises,        )        policy6 = CFRPolicy(strategy=r6.strategy)        policy6.save_json(            cfg.preflop_6max_out,            iterations=r6.iterations,            exploitability_mbb=r6.exploitability_mbb or -1.0,        )        preflop_6 = r6.num_info_sets        rhu = solve_preflop(            num_players=2,            iterations=cfg.preflop_iters_hu,            chance_samples=max(16, cfg.chance_samples),            workers=workers,            max_raises=cfg.max_raises,        )        policy_hu = CFRPolicy(strategy=rhu.strategy)        policy_hu.save_json(            cfg.preflop_hu_out,            iterations=rhu.iterations,            exploitability_mbb=rhu.exploitability_mbb or -1.0,        )        preflop_hu = rhu.num_info_sets    solver_spots = 0    student_mse: float | None = None    if cfg.solver_grid:        from poker_ai.solver.bridge.batch import solve_grid        from poker_ai.solver.bridge.texas import Backend        b_raw = cfg.solver_backend.strip().lower()        backend: Backend = "auto" if b_raw not in ("mock", "texas") else b_raw  # type: ignore[assignment]        grid = solve_grid(            n_spots=cfg.solver_grid_spots,            cache_dir=cfg.cache_dir,            backend=backend,            seed=42,        )        solver_spots = grid.solved + grid.cache_hits    if cfg.train_student:        from poker_ai.learn.train_student import TrainStudentConfig, run_train_student        from poker_ai.solver.bridge.cache import SolverCache        cache = SolverCache(cfg.cache_dir)        if cache.stats()["count"] == 0:            msg = (                f"No solver cache at {cfg.cache_dir} — run with --solver-grid first "                "or `poker_ai solve grid`."            )            raise ValueError(msg)        sm = run_train_student(            artifact_dir=cfg.student_dir,            hhformer_dir=cfg.hhformer_dir,            cache_dir=cfg.cache_dir,            cfg=TrainStudentConfig(                epochs=cfg.student_epochs,                batch_size=cfg.student_batch_size,            ),        )        student_mse = sm.mse_val    manifest = {        "workers": workers,        "hands_ingested": hands_ingested,        "features_written": features_written,        "embeddings_written": embeddings_written,        "preflop_6_info_sets": preflop_6,        "preflop_hu_info_sets": preflop_hu,        "solver_spots_cached": solver_spots,        "student_mse_val": student_mse,        "solver_grid": cfg.solver_grid,        "train_student": cfg.train_student,        "finished_at": datetime.now(tz=UTC).isoformat(),    }    manifest_path = Path("artifacts/pipeline_manifest.json")    manifest_path.parent.mkdir(parents=True, exist_ok=True)    manifest_path.write_text(json.dumps(manifest, indent=2), encoding="utf-8")    return PipelineResult(        hands_ingested=hands_ingested,        features_written=features_written,        embeddings_written=embeddings_written,        preflop_6_info_sets=preflop_6,        preflop_hu_info_sets=preflop_hu,        solver_spots_cached=solver_spots,        student_mse_val=student_mse,    )